<div class="student-detail-grid">
<section class="approval-panel"><h2>Thông tin định danh</h2><dl class="student-info"><div><dt>MSSV</dt><dd><?= $escape($student['MSSV']) ?></dd></div><div><dt>CCCD</dt><dd><?= $escape($student['CCCD']) ?></dd></div><div><dt>Niên khóa</dt><dd><?= $escape($student['NienKhoa']) ?></dd></div><div><dt>Trạng thái</dt><dd><?= $escape($student['TrangThaiLuuTru']) ?></dd></div><div><dt>Email</dt><dd><?= $escape($student['Email']?:'Chưa cập nhật') ?></dd></div></dl></section>
<section class="approval-panel"><h2>Thông tin lưu trú</h2><dl class="student-info"><div><dt>Hợp đồng</dt><dd><?= $escape($student['MaHopDong']?:'Chưa có') ?></dd></div><div><dt>Phòng</dt><dd><?= $escape($student['SoPhong']?:'Chưa bố trí') ?></dd></div><div><dt>Tòa nhà</dt><dd><?= $escape($student['TenToa']?:'—') ?></dd></div><div><dt>Trạng thái HĐ</dt><dd><?= $escape($student['TrangThaiHopDong']?:'—') ?></dd></div></dl></section>
</div>
<section class="approval-panel student-edit-panel"><h2>Cập nhật thông tin</h2><form id="student-update-form" class="student-edit-form" method="post" action="<?= $url('index.php?action=student-update') ?>"><input type="hidden" name="student" value="<?= $escape($student['MSSV']) ?>">
<?php foreach(['HoTen'=>'Họ và tên','NgaySinh'=>'Ngày sinh','QueQuan'=>'Quê quán','SDT'=>'Số điện thoại','Lop'=>'Lớp'] as $field=>$label):?><label><?= $label ?><input type="<?= $field==='NgaySinh'?'date':'text' ?>" name="<?= $field ?>" maxlength="<?= ['HoTen'=>100,'NgaySinh'=>10,'QueQuan'=>150,'SDT'=>15,'Lop'=>30][$field] ?>" value="<?= $escape($student[$field]) ?>" required><?php if(isset($errors[$field])):?><span class="student-field-error"><?= $escape($errors[$field]) ?></span><?php endif;?></label><?php endforeach;?>
<label>Giới tính<select name="GioiTinh" required><?php foreach(['Nam','Nữ'] as $gender):?><option value="<?= $gender ?>"<?= $student['GioiTinh']===$gender?' selected':'' ?>><?= $gender ?></option><?php endforeach;?></select><?php if(isset($errors['GioiTinh'])):?><span class="student-field-error"><?= $escape($errors['GioiTinh']) ?></span><?php endif;?></label>
<div class="student-edit-actions"><a class="approval-button" href="<?= $url('index.php?action=student-detail&id='.rawurlencode($student['MSSV'])) ?>">Hủy</a><button class="approval-button primary" type="button" data-open="student-update-confirm">Lưu thay đổi</button></div></form></section>
<dialog class="approval-dialog" id="student-update-confirm"><h2>Xác nhận cập nhật</h2><p>Bạn có chắc chắn muốn lưu các thay đổi này không?</p><div class="approval-actions"><button class="approval-button" type="button" data-close>Hủy</button><button class="approval-button primary" type="submit" form="student-update-form">Có, lưu thay đổi</button></div></dialog>
